/* ANN-UNG · anfitrion.js — el anfitrión con sus 7 caras, mirada, compañero flotante y pantallazo.
   Instalación: subir este archivo junto a index.html y añadir antes de </body>:
   <script src="./anfitrion.js" defer></script>  */
(()=>{'use strict';
const SP={"main":"data:image/webp;base64,","hi":"data:image/webp;base64,","serio":"data:image/webp;base64,","como":"data:image/webp;base64,","secreto":"data:image/webp;base64,","noabras":"data:image/webp;base64,","yaque":"data:image/webp;base64,"};
const MAP={main:'main',radiant:'hi',crossed:'serio',surprised:'como',whisper:'secreto',furious:'noabras',resigned:'yaque'};
const $=s=>document.querySelector(s);
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches, fine=matchMedia('(pointer: fine)').matches;
const lang=()=>{const b=$('.lang-switch [aria-pressed="true"]'),l=b?b.dataset.lang:'es';return l==='babel'?['es','en','de'][Math.random()*3|0]:l;};
const LINES={
es:[['crossed','¿Sigues ahí? Qué persistencia tan sospechosa.'],['whisper','(Te lo digo en secreto: las pistas están donde menos miras.)'],['surprised','¡¿Cómo?! ¿Todavía no has pulsado nada?'],['radiant','¡Bienvenido otra vez! Te estaba ignorando con cariño.'],['resigned','…bueno, ya que estás, sigue explorando.']],
en:[['crossed','Still here? How suspiciously persistent.'],['whisper','(Secret tip: the hints are where you least expect them.)'],['surprised','How?! You haven’t pressed anything yet?'],['radiant','Welcome back! I was ignoring you fondly.'],['resigned','…well, since you’re here, keep exploring.']],
de:[['crossed','Immer noch da? Verdächtig hartnäckig.'],['whisper','(Geheimtipp: Die Hinweise liegen dort, wo Sie nicht hinsehen.)'],['surprised','Wie bitte?! Sie haben noch nichts gedrückt?'],['radiant','Willkommen zurück! Ich habe Sie liebevoll ignoriert.'],['resigned','…na gut, wenn Sie schon hier sind, stöbern Sie weiter.']]};
const BIG={es:'¡NO LO ABRAS!',en:'DO NOT OPEN IT!',de:'NICHT ÖFFNEN!'};
let off=false;try{off=sessionStorage.getItem('annHostOff')==='1';}catch(e){}
const css=document.createElement('style');
css.textContent=`#hostBuddy{position:fixed;z-index:70;left:14px;bottom:14px;width:104px;pointer-events:none;opacity:0;transform:translateY(40px);transition:opacity .35s,transform .5s cubic-bezier(.2,1.4,.4,1),left .9s ease-out,top .9s ease-out}#hostBuddy.on{opacity:1;transform:none}#hostBuddy img{display:block;width:100%;height:auto;pointer-events:auto;cursor:pointer;filter:drop-shadow(0 0 1px #fff) drop-shadow(0 0 8px #c5a7ff77)}#hostBuddy .b{position:absolute;left:92%;bottom:62%;width:min(230px,58vw);padding:9px 24px 9px 11px;background:#f0e8ff;color:#191126;border-radius:12px 12px 12px 2px;font:12px/1.4 'Space Grotesk',system-ui,sans-serif;opacity:0;transform:scale(.92);transform-origin:0 100%;transition:.2s}#hostBuddy.say .b{opacity:1;transform:none}#hostBuddy .x{position:absolute;right:3px;top:2px;border:0;background:none;color:#191126;font:700 15px/1 sans-serif;cursor:pointer;pointer-events:auto;min-width:26px;min-height:26px}#hostBig{position:fixed;inset:0;z-index:85;display:none;place-items:center;align-content:center;gap:6px;background:#050309d9;cursor:pointer;text-align:center}#hostBig.on{display:grid}#hostBig img{height:min(70vh,520px);width:auto;max-width:92vw;filter:drop-shadow(0 0 2px #fff) drop-shadow(0 0 30px #ff426988)}#hostBig b{font:800 clamp(24px,6vw,52px)/1 'DM Mono',monospace;color:#ff4269;letter-spacing:.06em;text-shadow:0 0 18px #ff174d}`;
document.head.appendChild(css);
/* 1) Sprite principal en la tarjeta (el SVG queda oculto y sigue mandando las expresiones) */
const svg=$('#mascot');let card=null;
if(svg){svg.style.display='none';card=new Image();card.id='hostSprite';
card.style.cssText='display:block;width:auto;height:240px;max-width:100%;margin:4px auto;object-fit:contain;transition:transform .15s ease-out;filter:drop-shadow(0 0 1px #fff) drop-shadow(0 0 8px #c5a7ff66)';
svg.after(card);
const sync=()=>{const e=svg.dataset.expression||'main';card.src=SP[MAP[e]||'main'];card.alt='Monigote: '+e;};
sync();new MutationObserver(sync).observe(svg,{attributes:true,attributeFilter:['data-expression']});
if(!reduce&&card.animate)card.animate([{translate:'0 0'},{translate:'0 -6px'},{translate:'0 0'}],{duration:3200,iterations:Infinity,easing:'ease-in-out'});}
/* 2) Compañero flotante */
const buddy=document.createElement('div');buddy.id='hostBuddy';buddy.setAttribute('aria-hidden','true');
buddy.innerHTML='<div class="b"><span></span><button class="x" type="button" tabindex="-1">×</button></div><img alt="">';
document.body.appendChild(buddy);
const bimg=buddy.querySelector('img'),bsay=buddy.querySelector('.b span');let n=0,tt;
function say(face,text){bimg.src=SP[MAP[face]||'radiant'];bsay.textContent=text;buddy.classList.add('on','say');clearTimeout(tt);tt=setTimeout(()=>buddy.classList.remove('say'),4800);}
function nextLine(){const l=LINES[lang()]||LINES.es,i=l[n++%l.length];say(i[0],i[1]);}
bimg.addEventListener('click',()=>{if(svg){const k=Object.keys(MAP);svg.dataset.expression=k[n%k.length];}nextLine();});
buddy.querySelector('.x').addEventListener('click',()=>{off=true;try{sessionStorage.setItem('annHostOff','1');}catch(e){}buddy.classList.remove('on','say');});
const loop=()=>{if(!off&&!document.hidden)nextLine();setTimeout(loop,22000+Math.random()*14000);};
if(!off){setTimeout(()=>{nextLine();setTimeout(loop,22000);},7000);}
/* 3) Mirada (inclina la cara hacia el puntero) y seguimiento del compañero (solo con ratón) */
let px=0,py=0,raf=0;
addEventListener('pointermove',e=>{px=e.clientX;py=e.clientY;if(raf||reduce)return;raf=requestAnimationFrame(()=>{raf=0;
if(card){const r=card.getBoundingClientRect(),x=Math.max(-1,Math.min(1,(px-r.left-r.width/2)/innerWidth*2)),y=Math.max(-1,Math.min(1,(py-r.top-r.height/2)/innerHeight*2));card.style.transform='translate('+x*7+'px,'+y*4+'px) rotate('+x*5+'deg)';}
if(fine&&!off&&buddy.classList.contains('on')){buddy.style.bottom='auto';buddy.style.left=Math.max(8,Math.min(innerWidth-120,px+34))+'px';buddy.style.top=Math.max(8,Math.min(innerHeight-130,py+34))+'px';}});},{passive:true});
/* 4) Pantallazo: el anfitrión tapa la pantalla (clic, toque o Esc para cerrar) */
const big=document.createElement('div');big.id='hostBig';big.setAttribute('aria-hidden','true');big.innerHTML='<img alt=""><b></b>';document.body.appendChild(big);
let bt;function cover(face,text){if(off&&!face)return;big.querySelector('img').src=SP[MAP[face||'furious']];big.querySelector('b').textContent=text||BIG[lang()]||BIG.es;big.classList.add('on');clearTimeout(bt);bt=setTimeout(close,2600);}
function close(){big.classList.remove('on');}
big.addEventListener('click',close);addEventListener('keydown',e=>{if(e.key==='Escape')close();});
['#noOpenRepeat','#fakeDoor'].forEach(s=>{const el=$(s);if(el)el.addEventListener('click',()=>cover('furious'));});
setTimeout(()=>{if(!off)cover('furious');},45000);
})();
